package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class JsonWriter_value_TriageGen1Test {

    @Test
    public void testValue_NormalDouble() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.beginObject();
        writer.name("test");
        writer.value(123.45);
        writer.endObject();

        assertEquals("{\"test\":123.45}", out.toString());
    }

    @Test
    public void testValue_Zero() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.beginArray();
        writer.value(0.0);
        writer.endArray();

        assertEquals("[0.0]", out.toString());
    }

    @Test
    public void testValue_Negative() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.beginArray();
        writer.value(-1.0);
        writer.endArray();

        assertEquals("[-1.0]", out.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NaN() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.beginObject();
        writer.name("nan");
        writer.value(Double.NaN);
        writer.endObject();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_PositiveInfinity() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.beginObject();
        writer.name("inf");
        writer.value(Double.POSITIVE_INFINITY);
        writer.endObject();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValue_NegativeInfinity() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.beginObject();
        writer.name("negInf");
        writer.value(Double.NEGATIVE_INFINITY);
        writer.endObject();
    }

    @Test
    public void testValue_FluentApi() throws IOException {
        StringWriter out = new StringWriter();
        JsonWriter writer = new JsonWriter(out);
        writer.beginArray();
        JsonWriter returnedWriter = writer.value(1.0);
        writer.endArray();

        assertEquals(writer, returnedWriter);
        assertEquals("[1.0]", out.toString());
    }
}
